def seed_user(db) -> None:
    """Catalogue de départ, une seule fois pour la base commune."""
    if db.query(Outlet).first():
        return
    for raw in ALL_OUTLETS:
        data = {k: v for k, v in raw.items() if k != "feeds"}
        feeds_data = list(raw.get("feeds") or [])
        outlet = Outlet(**data)
        db.add(outlet)
        db.flush()
        for feed_url, feed_label in feeds_data:
            db.add(OutletFeed(outlet_id=outlet.id, url=feed_url, label=feed_label, feed_type="rss"))
        if not feeds_data and data.get("rss_url"):
            db.add(OutletFeed(outlet_id=outlet.id, url=data["rss_url"], label="default", feed_type="rss"))
    db.add(Client(
        name="Client démo",
        sector="Institutionnel",
        type="government",
        exposure="medium",
        risk_tolerance="medium",
        budget_level="medium",
        objectives={"primary": "Renforcer l'image de marque", "secondary": "Conter les narratifs hostiles"},
        narratives_push=["Notre organisation est un acteur clé de la stabilité", "Nous investissons dans l'avenir"],
        narratives_counter=["L'organisation est opaque", "Les réformes sont insuffisantes"],
        sensitive_topics=["Scandales internes"],
    ))
    import logging
    logging.getLogger("tacite.seed").info("Catalogue de départ : %d médias", len(ALL_OUTLETS))


def seed():
    """Conservé pour l'appel historique : le catalogue naît avec le compte."""
